using System;
using System.Windows.Forms;
using MySqlConnector;
using BC = BCrypt.Net.BCrypt;
namespace biblioteca_galvao { public partial class Login : Form { public Login() { InitializeComponent(); } private void loginConta_Click(object sender, EventArgs e) { string login=txtUsuario.Text, senha=txtSenha.Text; if(login==""||senha=="") { MessageBox.Show("Informe o seu login e senha!"); return; } try { using(MySqlConnection conexao=MySqlConnector.Conectar()) { conexao.Open(); string sql="Select id, usuario, senha From usuario Where email = @login OR usuario = @login LIMIT 1"; using(MySqlCommand comando=new MySqlCommand(sql,conexao)) { comando.Parameters.AddWithValue("@login",login); using(MySqlDataReader leitor=comando.ExecuteReader()) { if(leitor.Read()) { string senhaHash=leitor["senha"].ToString(); bool senhaCorreta=BC.Verify(senha,senhaHash); if(senhaCorreta) { MessageBox.Show("Login realizado com sucesso!"); TelaPrincipal principalScreen=new TelaPrincipal(); principalScreen.FormClosed+=(s,arg)=>this.Close(); principalScreen.Show(); this.Hide(); return; } } } } } MessageBox.Show("Usuario ou senha incorretos!"); } catch(Exception erro) { MessageBox.Show("Erro ao realizar o login: "+erro.Message); } } private void txtUsuario_TextChanged(object sender, EventArgs e) { } private void txtSenha_TextChanged(object sender, EventArgs e) { } private void cadastroBtn_Click(object sender, EventArgs e) { Cadastro cadastrarLgn=new Cadastro(); cadastrarLgn.Show(); this.Hide(); } } }